//! Emergency operations plan (EOP) generation.
//!
//! Drafts are generated by the Tier-2 AI capability from the event, its linked
//! hazards, the SOS resource inventory and the operator's additional context.
//! `metadata.generated_by` is `tier2-ai` and records the model, prompt version
//! and token usage.
//!
//! A deterministic, event-specific doctrine draft is still available as an
//! explicit, clearly labelled fallback (`generated_by:
//! "deterministic-fallback"`). It is never used silently: the API returns a
//! typed `503 ai_capability_unavailable` unless the caller opts in, and the
//! fallback itself is never an all-empty skeleton.

use crate::domain::error::{bad_gateway, DomainError};
use crate::domain::filters::{
    js_number, js_string, js_truthy, non_null, now_iso, number_text, string_or, Data,
};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::collections::HashSet;

pub const EOP_PROMPT_VERSION: &str = "sos-eop-prompt-v1";

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct EopAction {
    pub action_id: String,
    pub title: String,
    pub description: String,
    pub phase: String,
    pub priority: String,
    pub owner_role: String,
    pub estimated_minutes: i64,
    pub dependencies: Vec<String>,
    pub required_capability: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct EopAssignment {
    pub action_id: String,
    pub resource_unit_id: Option<String>,
    pub assignee_id: Option<String>,
    pub required_capability: String,
    pub status: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct EopDraft {
    pub title: String,
    pub summary: String,
    pub status: String,
    pub version: u32,
    pub objectives: Vec<String>,
    pub operational_phases: Vec<String>,
    pub actions: Vec<EopAction>,
    pub assignment_matrix: Vec<EopAssignment>,
    pub evacuation_plan: Vec<String>,
    pub fallback_plan: Vec<String>,
    pub communications_plan: Vec<String>,
    pub markdown_body: String,
    pub metadata: Data,
}

#[derive(Debug, Clone)]
pub struct DraftContext<'a> {
    pub event: &'a Data,
    pub hazards: &'a [Data],
    pub resources: &'a [Data],
    pub title: Option<String>,
    pub additional_context: Option<String>,
    pub generated_at: Option<String>,
}

impl<'a> DraftContext<'a> {
    pub fn new(event: &'a Data) -> Self {
        Self {
            event,
            hazards: &[],
            resources: &[],
            title: None,
            additional_context: None,
            generated_at: None,
        }
    }

    pub fn with_hazards(mut self, hazards: &'a [Data]) -> Self {
        self.hazards = hazards;
        self
    }

    pub fn with_resources(mut self, resources: &'a [Data]) -> Self {
        self.resources = resources;
        self
    }

    pub fn with_title(mut self, title: impl Into<String>) -> Self {
        self.title = Some(title.into());
        self
    }

    pub fn with_additional_context(mut self, context: impl Into<String>) -> Self {
        self.additional_context = Some(context.into());
        self
    }

    pub fn with_generated_at(mut self, generated_at: impl Into<String>) -> Self {
        self.generated_at = Some(generated_at.into());
        self
    }
}

fn type_label(event_type: &str) -> &'static str {
    match event_type {
        "flood" => "lũ lụt",
        "storm" => "bão",
        "landslide" => "sạt lở",
        "fire" => "cháy",
        "earthquake" => "động đất",
        "outage" => "mất điện",
        "pollution" => "ô nhiễm",
        "drought" => "hạn hán",
        "traffic" => "ùn tắc giao thông",
        "epidemic" => "dịch bệnh",
        _ => "sự cố",
    }
}

fn severity_priority(severity: &str) -> &'static str {
    match severity {
        "low" => "low",
        "high" => "high",
        "critical" => "critical",
        _ => "medium",
    }
}

fn severity_label(severity: &str) -> Option<&'static str> {
    match severity {
        "low" => Some("thấp"),
        "medium" => Some("trung bình"),
        "high" => Some("cao"),
        "critical" => Some("nghiêm trọng"),
        _ => None,
    }
}

