fn type_actions(event_type: &str) -> &'static [ActionSeed] {
    match event_type {
        "storm" => STORM_ACTIONS,
        "landslide" => LANDSLIDE_ACTIONS,
        "earthquake" => EARTHQUAKE_ACTIONS,
        "fire" => FIRE_ACTIONS,
        _ => FLOOD_ACTIONS,
    }
}

fn action_seeds(event_type: &str) -> Vec<&'static ActionSeed> {
    type_actions(event_type)
        .iter()
        .chain(COMMON_ACTIONS.iter())
        .collect()
}

fn capability_available(resources: &[Data], capability: &str) -> bool {
    let resource_type = if capability == "medical" {
        "medical_supply"
    } else {
        capability
    };
    resources.iter().any(|resource| {
        let status = string_or(resource, "status", "available");
        if status == "offline" || status == "maintenance" {
            return false;
        }
        let kind = string_or(resource, "resource_type", "");
        if capability == "personnel" {
            return kind == "personnel";
        }
        if capability == "communications" {
            return kind == "personnel"
                || kind == "vehicle"
                || resource.contains_key("metadata");
        }
        kind == resource_type || kind == "personnel" || kind == "vehicle"
    })
}

fn location_text(event: &Data) -> String {
    let Some(location) = event.get("location").and_then(Value::as_object) else {
        return String::new();
    };
    ["address", "ward", "district", "city"]
        .iter()
        .filter_map(|key| {
            location
                .get(*key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string)
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn hazard_summary(hazards: &[Data]) -> String {
    if hazards.is_empty() {
        return "Không có lớp cảnh báo liên kết.".to_string();
    }
    hazards
        .iter()
        .take(5)
        .map(|hazard| {
            let title = non_null(hazard, "title")
                .or_else(|| non_null(hazard, "id"))
                .map(js_string)
                .unwrap_or_else(|| "undefined".to_string());
            let severity = non_null(hazard, "severity")
                .map(js_string)
                .unwrap_or_else(|| "n/a".to_string());
            format!("{title} ({severity})")
        })
        .collect::<Vec<_>>()
        .join("; ")
}

fn owner_role_for_phase(phase: &str) -> &'static str {
    match phase {
        "recover" => "recovery_lead",
        "prepare" => "preparedness_lead",
        _ => "operations_lead",
    }
}

fn default_draft_title(event: &Data) -> String {
    let title = non_null(event, "title")
        .map(js_string)
        .unwrap_or_else(|| "Sự kiện khẩn cấp".to_string());
    format!("EOP — {title}")
}

/// Build a deterministic, event-specific EOP draft.
pub fn build_eop_draft(context: &DraftContext<'_>, version: Option<u32>) -> EopDraft {
    let event = context.event;
    let hazards = context.hazards;
    let resources = context.resources;
    let version = version.unwrap_or(1);
    let event_type = string_or(event, "event_type", "other");
    let severity = string_or(event, "severity", "medium");
    let priority = severity_priority(&severity);
    let type_label = type_label(&event_type);
    let location = location_text(event);
    let title = context
        .title
        .as_deref()
        .map(str::trim)
        .filter(|title| !title.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| default_draft_title(event));
    let generated_at = context.generated_at.clone().unwrap_or_else(now_iso);

    let actions: Vec<EopAction> = action_seeds(&event_type)
        .into_iter()
        .map(|seed| EopAction {
            action_id: seed.id.to_string(),
            title: seed.title.to_string(),
            description: if location.is_empty() {
                seed.description.to_string()
            } else {
                format!("{} Khu vực: {}.", seed.description, location)
            },
            phase: seed.phase.to_string(),
            priority: priority.to_string(),
            owner_role: owner_role_for_phase(seed.phase).to_string(),
            estimated_minutes: seed.minutes,
            dependencies: seed.depends.iter().map(|dep| (*dep).to_string()).collect(),
            required_capability: seed.capability.to_string(),
        })
        .collect();

    let assignment_matrix: Vec<EopAssignment> = actions
        .iter()
        .map(|action| EopAssignment {
            action_id: action.action_id.clone(),
            resource_unit_id: None,
            assignee_id: None,
            required_capability: action.required_capability.clone(),
            status: "pending".to_string(),
        })
        .collect();

    let severity_text = severity_label(&severity)
        .map(str::to_string)
        .unwrap_or_else(|| severity.clone());
    let objectives = vec![
        format!(
            "Bảo vệ tính mạng người dân tại {} trong tình huống {}.",
            if location.is_empty() {
                "khu vực ảnh hưởng".to_string()
            } else {
                location.clone()
            },
            type_label
        ),
        format!(
            "Duy trì chỉ huy thống nhất và nhịp báo cáo SITREP 6 giờ/lần ở mức {severity_text}."
        ),
        "Bảo đảm nguồn lực cứu hộ, y tế và nơi trú ẩn được điều phối theo thứ tự ưu tiên."
            .to_string(),
        "Khôi phục dịch vụ thiết yếu và hoàn tất AAR trong vòng 72 giờ sau khi kết thúc."
            .to_string(),
    ];

    let mut capability_gaps: Vec<String> = Vec::new();
    for action in &actions {
        if !capability_gaps.contains(&action.required_capability)
            && !capability_available(resources, &action.required_capability)
        {
            capability_gaps.push(action.required_capability.clone());
        }
    }

    let evacuated = event
        .get("estimated_impact")
        .and_then(Value::as_object)
        .and_then(|impact| impact.get("evacuated_people"))
        .and_then(|value| js_number(Some(value)))
        .filter(|value| *value != 0.0)
        .map(number_text)
        .unwrap_or_else(|| "toàn bộ".to_string());
    let evacuation_plan = vec![
        format!(
            "Xác định khu vực ưu tiên sơ tán: {}.",
            if location.is_empty() {
                "theo bản đồ nguy cơ SOS".to_string()
            } else {
                location.clone()
            }
        ),
        format!("Bố trí nơi trú ẩn cho {evacuated} người dân trong vùng ảnh hưởng."),
        "Ưu tiên người già, trẻ em, người khuyết tật và hộ dân tại khu vực ngập sâu/sạt lở."
            .to_string(),
        "Bảo đảm tuyến sơ tán không trùng với điểm phong tỏa và có phương án dự phòng."
            .to_string(),
    ];

    let fallback_plan = vec![
        "Nếu mất liên lạc, chuyển sang kênh vô tuyến dự phòng và cử liên lạc viên tới hiện trường."
            .to_string(),
        "Nếu thiếu nguồn lực tại chỗ, điều động từ quận/huyện lân cận theo thứ tự ưu tiên đã duyệt."
            .to_string(),
        "Nếu điều kiện thời tiết xấu, tạm dừng hoạt động ngoài trời và duy trì cứu hộ khẩn cấp."
            .to_string(),
    ];

    let communications_plan = vec![
        "Phát cảnh báo công khai trên bản đồ SOS, loa phường và tin nhắn khẩn cấp.".to_string(),
        "Duy trì cập nhật SITREP mỗi 6 giờ và báo cáo đột xuất khi có thương vong.".to_string(),
        "Chỉ định người phát ngôn duy nhất và kiểm soát tin đồn trên mạng xã hội.".to_string(),
    ];

    let source_refs = json!({
        "emergency_event_id": event.get("id").cloned().unwrap_or(Value::Null),
        "hazard_ids": hazards
            .iter()
            .map(|hazard| {
                hazard
                    .get("id")
                    .map(js_string)
                    .unwrap_or_else(|| "undefined".to_string())
            })
            .collect::<Vec<_>>(),
        "resource_unit_ids": resources
            .iter()
            .map(|resource| {
                resource
                    .get("id")
                    .map(js_string)
                    .unwrap_or_else(|| "undefined".to_string())
            })
            .collect::<Vec<_>>()
    });
    let metadata = json!({
        "generated_by": "deterministic-fallback",
        "generated_at": generated_at,
        "generator": "sos-eop-doctrine-v1",
        "prompt_version": null,
        "ai_provider": null,
        "model": null,
        "source_refs": source_refs,
        "additional_context": context.additional_context.clone().map(Value::String).unwrap_or(Value::Null),
        "capability_gaps": capability_gaps,
    });
    let metadata = metadata.as_object().cloned().unwrap_or_default();

    let event_title = non_null(event, "title")
        .map(js_string)
        .unwrap_or_else(|| "sự kiện khẩn cấp".to_string());
    let summary = format!(
        "Kế hoạch ứng phó {} cho {}{}.",
        type_label,
        event_title,
        if location.is_empty() {
            String::new()
        } else {
            format!(" tại {location}")
        }
    );

    let mut draft = EopDraft {
        title,
        summary,
        status: "draft".to_string(),
        version,
        objectives,
        operational_phases: vec![
            "prepare".to_string(),
            "respond".to_string(),
            "recover".to_string(),
        ],
        actions,
        assignment_matrix,
        evacuation_plan,
        fallback_plan,
        communications_plan,
        markdown_body: String::new(),
        metadata,
    };
    draft.markdown_body = render_eop_markdown(&draft, context);
    draft
}

/// Render the operator-facing Markdown body for any draft (AI or fallback).
pub fn render_eop_markdown(draft: &EopDraft, context: &DraftContext<'_>) -> String {
    let event = context.event;
    let location = location_text(event);
    let metadata = &draft.metadata;
    let generated_by = string_or(metadata, "generated_by", "deterministic-fallback");
    let model = metadata
        .get("model")
        .filter(|value| js_truthy(value))
        .map(js_string);
    let generated_at = metadata
        .get("generated_at")
        .filter(|value| !value.is_null())
        .map(js_string)
        .unwrap_or_else(now_iso);
    let capability_gaps: Vec<String> = match metadata.get("capability_gaps") {
        Some(Value::Array(items)) => items.iter().map(js_string).collect(),
        _ => Vec::new(),
    };

    let resource_lines: Vec<String> = if context.resources.is_empty() {
        vec![
            "Chưa có nguồn lực SOS trong hệ thống — cần bổ sung trước khi submit."
                .to_string(),
        ]
    } else {
        context
            .resources
            .iter()
            .take(8)
            .map(|resource| {
                let name = non_null(resource, "name")
                    .or_else(|| non_null(resource, "id"))
                    .map(js_string)
                    .unwrap_or_else(|| "undefined".to_string());
                format!(
                    "- {}: {} · {} · {}",
                    name,
                    string_or(resource, "status", "unknown"),
                    string_or(resource, "resource_type", "n/a"),
                    string_or(resource, "district", "chưa rõ khu vực")
                )
            })
            .collect()
    };

    let source_line = if generated_by == "tier2-ai" {
        format!(
            "AI ({}) · prompt {}",
            model.unwrap_or_else(|| "tier-2 model".to_string()),
            string_or(metadata, "prompt_version", EOP_PROMPT_VERSION)
        )
    } else {
        "deterministic-fallback (không có AI)".to_string()
    };

    let event_code = non_null(event, "event_code")
        .or_else(|| non_null(event, "id"))
        .map(js_string)
        .unwrap_or_else(|| "undefined".to_string());
    let event_title = non_null(event, "title")
        .map(js_string)
        .unwrap_or_default();
    let event_type = string_or(event, "event_type", "other");
    let severity = string_or(event, "severity", "medium");
    let severity_text = severity_label(&severity)
        .map(str::to_string)
        .unwrap_or_else(|| severity.clone());

    let mut lines: Vec<String> = Vec::new();
    lines.push(format!("# {}", draft.title));
    lines.push(String::new());
    lines.push(format!("- Sự kiện: {event_code} — {event_title}"));
    lines.push(format!(
        "- Loại: {}; mức độ: {severity_text}",
        type_label(&event_type)
    ));
    lines.push(format!(
        "- Địa điểm: {}",
        if location.is_empty() {
            "chưa xác định"
        } else {
            location.as_str()
        }
    ));
    lines.push(format!(
        "- Cảnh báo liên kết: {}",
        hazard_summary(context.hazards)
    ));
    lines.push(format!(
        "- Bản nháp: v{} · tạo lúc {generated_at} · nguồn: {source_line}",
        draft.version
    ));
    lines.push(String::new());
    lines.push("## Mục tiêu".to_string());
    lines.extend(draft.objectives.iter().map(|objective| format!("- {objective}")));
    lines.push(String::new());
    lines.push("## Hành động".to_string());
    lines.extend(draft.actions.iter().map(|action| {
        format!(
            "- [{}] {} — {} ({} phút)",
            action.phase, action.title, action.description, action.estimated_minutes
        )
    }));
    lines.push(String::new());
    lines.push("## Ma trận phân công".to_string());
    lines.extend(draft.assignment_matrix.iter().map(|assignment| {
        format!(
            "- {}: {} ({})",
            assignment.action_id, assignment.required_capability, assignment.status
        )
    }));
    lines.push(String::new());
    lines.push("## Sơ tán".to_string());
    lines.extend(draft.evacuation_plan.iter().map(|line| format!("- {line}")));
    lines.push(String::new());
    lines.push("## Phương án dự phòng".to_string());
    lines.extend(draft.fallback_plan.iter().map(|line| format!("- {line}")));
    lines.push(String::new());
    lines.push("## Truyền thông".to_string());
    lines.extend(
        draft
            .communications_plan
            .iter()
            .map(|line| format!("- {line}")),
    );
    lines.push(String::new());
    lines.push("## Nguồn lực hiện có".to_string());
    lines.extend(resource_lines);
    lines.push(String::new());
    lines.push("## Thiếu hụt năng lực".to_string());
    if capability_gaps.is_empty() {
        lines.push("- Không phát hiện thiếu hụt từ danh mục hiện tại.".to_string());
    } else {
        lines.extend(capability_gaps.iter().map(|gap| format!("- {gap}")));
    }
    lines.push(String::new());
    if let Some(additional) = context
        .additional_context
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        lines.push("## Ghi chú bổ sung".to_string());
        lines.push(additional.to_string());
    } else {
        lines.push(String::new());
        lines.push(String::new());
    }

    lines
        .into_iter()
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
